//! Adoption changes native ownership without cloning nodes, Attr or collections.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div><div id=source data-note=original><span id=child>old</span><!--marker--></div><input id=field value=seed><form id=ownerForm><input id=tagField name=getElementsByTagName><input id=classField name=getElementsByClassName></form></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://node-adoption.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn node_adoption_inert_document_root_preserves_owner_tree_attr_views_author_fields_and_removal_records(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.implementation.createHTMLDocument('source'),root=source.documentElement,body=source.body,leaf=source.createElement('span'),target=document.implementation.createDocument('urn:target','q:Root'),watch=new MutationObserver(function(){});leaf.setAttribute('data-note','\ud800');body.appendChild(leaf);var attr=leaf.getAttributeNode('data-note'),list=root.childNodes,view=root.children,state={value:17};root.authorState=state;watch.observe(source,{subtree:true,childList:true,attributes:true});
if(target.adoptNode(root)!==root||root.ownerDocument!==target||root.parentNode!==null||root.tagName!=='html'||source.documentElement!==null||source.head!==null||source.body!==null||source.title!==''||target.documentElement.localName!=='Root'||root.authorState!==state||attr.ownerDocument!==target||attr.ownerElement!==leaf||attr.value.charCodeAt(0)!==0xd800||body.ownerDocument!==target||leaf.ownerDocument!==target||root.childNodes!==list||root.children!==view||list.length!==2)throw 'actual adoption records and aliases';
var records=watch.takeRecords();watch.disconnect();if(records.length!==1||records[0].target!==source||records[0].removedNodes[0]!==root||records[0].previousSibling!==source.doctype||records[0].nextSibling!==null)throw 'real source root removal';
target.documentElement.appendChild(root);var next=target.createElementNS('http://www.w3.org/1999/xhtml','span');root.appendChild(next);if(list.length!==3||list[2]!==next||view.length!==3||view[2]!==next||root.parentNode!==target.documentElement||attr.ownerDocument!==target||leaf.getAttributeNode('data-note')!==attr)throw 'saved adopted live views';
"#);
}
#[test]
fn node_adoption_native_export_saved_child_lists_ranges_attrs_and_same_identity_return_to_app_tree(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.getElementById('source'),child=source.firstChild,text=child.firstChild,attr=source.getAttributeNode('data-note'),list=source.childNodes,view=source.children,body=document.body,target=document.implementation.createDocument(null,''),watch=new MutationObserver(function(){}),range=new Range(),state={original:true};source.authorState=state;child.setAttribute('class','tracked');var tags=source.getElementsByTagName('span'),upper=source.getElementsByTagName('SPAN'),classes=source.getElementsByClassName('tracked');if(tags.length!==1||upper.length!==1||classes.length!==1)throw 'real initial scoped collections';watch.observe(body,{childList:true});range.setStart(text,1);range.setEnd(text,2);
if(target.adoptNode(source)!==source||source.parentNode!==null||source.ownerDocument!==target||child.ownerDocument!==target||text.ownerDocument!==target||attr.ownerDocument!==target||attr.ownerElement!==source||source.getAttributeNode('data-note')!==attr||source.authorState!==state||source.tagName!=='div'||source.childNodes!==list||source.children!==view||list[0]!==child||range.startContainer!==body||range.endContainer!==body||range.startOffset!==1||range.endOffset!==1)throw 'genuine native export and saved state';
var records=watch.takeRecords();watch.disconnect();if(records.length!==1||records[0].removedNodes[0]!==source||records[0].target!==body||document.getElementById('source')!==null)throw 'real main removal and lookup';
var next=target.createElementNS('http://www.w3.org/1999/xhtml','span');next.textContent='new';next.setAttribute('class','tracked');source.appendChild(next);text.data='changed';if(list.length!==3||list[2]!==next||view.length!==2||view[1]!==next||source.childNodes!==list||source.firstChild!==child)throw 'saved native views follow logical ownership';
if(tags.length!==2||tags[1]!==next||upper.length!==2||classes.length!==2||classes[1]!==next||source.getElementsByTagName('SPAN').length!==0)throw 'saved scope filter and current owner type';var exotic=target.createElement('span');source.appendChild(exotic);if(tags.length!==3||tags[2]!==exotic||upper.length!==2||classes.length!==2||exotic.namespaceURI!==null||exotic.ownerDocument!==target)throw 'saved collection returns genuine unreserved data identity';source.removeChild(exotic);if(tags.length!==2)throw 'current removed scope member';
if(document.adoptNode(source)!==source||source.ownerDocument!==document||attr.ownerDocument!==document||source.tagName!=='DIV'||source.childNodes!==list)throw 'same identity main owner return';
var fragment=target.createDocumentFragment();document.adoptNode(fragment);fragment.appendChild(source);document.getElementById('mount').appendChild(fragment);if(source.parentNode!==document.getElementById('mount')||source.firstChild!==child||child.firstChild!==text||text.data!=='changed'||source.lastChild!==next||source.childNodes!==list||source.children!==view||list.length!==3||view.length!==2||source.authorState!==state||source.getAttributeNode('data-note')!==attr||attr.ownerDocument!==document||source.textContent!=='changednew')throw 'same IDs promoted with real changed data';
"#);
}
#[test]
fn node_adoption_attribute_document_is_native_and_parking_promotion_rebind_attached_records(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var node=document.getElementById('source'),attr=node.getAttributeNode('data-note'),other=document.implementation.createDocument(null,''),watch=new MutationObserver(function(){});watch.observe(node,{attributes:true});
if(other.adoptNode(attr)!==attr||attr.ownerDocument!==other||attr.ownerElement!==node||node.getAttributeNode('data-note')!==attr||attr.baseURI!==other.baseURI||watch.takeRecords().length)throw 'actual Attr associated document';node.removeAttribute('data-note');if(attr.ownerElement!==null||attr.ownerDocument!==other||attr.value!=='original'||attr.baseURI!==other.baseURI)throw 'removal preserves Attr node document';document.adoptNode(attr);node.setAttributeNode(attr);if(attr.ownerDocument!==document||attr.ownerElement!==node||node.getAttributeNode('data-note')!==attr)throw 'real attachment document';watch.disconnect();
var fresh=document.createElement('div');fresh.setAttribute('data-note','held');var held=fresh.getAttributeNode('data-note'),list=fresh.childNodes,view=fresh.children,template=document.createElement('template'),content=template.content,owner=content.ownerDocument;content.appendChild(fresh);if(held.ownerDocument!==owner||fresh.ownerDocument!==owner||fresh.childNodes!==list)throw 'parked native Attr document';fresh.appendChild(owner.createElement('span'));if(list.length!==1||view.length!==1)throw 'parked native live views';document.getElementById('mount').appendChild(content);if(held.ownerDocument!==document||held.ownerElement!==fresh||fresh.getAttributeNode('data-note')!==held||fresh.childNodes!==list||list.length!==1||fresh.children!==view||view.length!==1)throw 'promoted native Attr document and views';
"#);
}
#[test]
fn node_adoption_document_brand_resources_same_owner_noop_and_doctype_are_checked(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var method=Document.prototype.adoptNode,target=document.implementation.createDocument(null,''),effects=0,caught=false;if(method.length!==1||method.name!=='adoptNode')throw 'canonical adoption';try{method.call({}, {toString:function(){effects++;return 'fake';}});}catch(e){caught=e instanceof TypeError;}if(!caught||effects)throw 'brand before author code';caught=false;try{target.adoptNode();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'required Node';
caught=false;try{target.adoptNode(document);}catch(e){caught=e.name==='NotSupportedError'&&e instanceof DOMException;}if(!caught)throw 'Document cannot be adopted';var field=document.getElementById('field');caught=false;try{target.adoptNode(field);}catch(e){caught=e.name==='NotSupportedError'&&e instanceof DOMException;}if(!caught||field.parentNode!==document.body||field.ownerDocument!==document||field.value!=='seed')throw 'native form lifecycle refusal';
var detached=document.createElement('input');if(document.adoptNode(detached)!==detached||detached.ownerDocument!==document||detached.parentNode!==null)throw 'same-owner detached noop';
var dtype=document.doctype;if(document.adoptNode(dtype)!==dtype||document.doctype!==null||dtype.parentNode!==null||dtype.ownerDocument!==document||dtype.name!=='html')throw 'native same-owner doctype removal';if(target.adoptNode(dtype)!==dtype||dtype.ownerDocument!==target||dtype.parentNode!==null||target.doctype!==null)throw 'native cross-owner doctype';target.appendChild(dtype);if(target.doctype!==dtype||dtype.parentNode!==target)throw 'actual adopted doctype insertion';
"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());
}
#[test]
fn node_adoption_collection_operations_are_canonical_and_keep_document_element_brands(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var docTag=Document.prototype.getElementsByTagName,elementTag=Element.prototype.getElementsByTagName,docClass=Document.prototype.getElementsByClassName,elementClass=Element.prototype.getElementsByClassName,d=Object.getOwnPropertyDescriptor(Element.prototype,'getElementsByTagName'),source=document.getElementById('source'),calls=0;
if(docTag===elementTag||docClass===elementClass||docTag.length!==1||elementTag.length!==1||docTag.name!=='getElementsByTagName'||elementClass.name!=='getElementsByClassName'||d.value!==elementTag||!d.writable||!d.enumerable||!d.configurable||source.getElementsByTagName!==elementTag||document.getElementsByTagName!==docTag)throw 'canonical collection descriptors';
for(var attempt of [function(){docTag.call(source,{toString:function(){calls++;return 'span';}});},function(){elementTag.call(document,{toString:function(){calls++;return 'span';}});},function(){elementClass.call({},'tracked');}]){var caught=false;try{attempt();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'correct collection interface brand';}if(calls)throw 'brand before name conversion';
var form=document.getElementById('ownerForm');if(form.getElementsByTagName!==document.getElementById('tagField')||form.getElementsByClassName!==document.getElementById('classField')||elementTag.call(form,'input').length!==2)throw 'named form fields precede prototype methods';
var owner=document.implementation.createDocument('\ud800','q:Root'),view=docTag.call(owner,'q:Root');if(!(view instanceof HTMLCollection)||view.length!==1||view[0]!==owner.documentElement||elementTag.call(owner.documentElement,'q:Root').length!==0||owner.getElementsByTagName!==docTag||owner.documentElement.getElementsByTagName!==elementTag)throw 'actual inert document and element scopes';
"#);
}
#[test]
fn node_adoption_saved_child_realm_method_revalidates_origin_before_any_owner_change(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var originSource=document.implementation.createDocument(null,''),target=document.implementation.createDocument(null,''),first=originSource.createElement('First'),pending=originSource.createElement('Pending'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Document.prototype.adoptNode;if(saved===Document.prototype.adoptNode||Object.getPrototypeOf(saved)!==w.Function.prototype||saved.call(target,first)!==first||first.ownerDocument!==target)throw 'actual saved child realm adoption';
"#);
 page.set_location(&crate::navigation::address("https://other-adoption-origin.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.dom_commits);
 assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(target,pending);").errors,1,"{}",page.report());assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.dom_commits),before);
 run(&mut doc,&mut forms,&mut page,"if(pending.ownerDocument!==originSource||pending.parentNode!==null||first.ownerDocument!==target)throw 'denied adoption has no owner prefix';");
}
